mapper.select:
SELECT id, tenant_id, program_id, member_id, account_no, account_type, status,
       opened_at, closed_at
FROM loyalty.account
WHERE tenant_id = #{tenantId} AND program_id = #{programId}
  AND member_id = #{memberId} AND id = #{id}

mapper.update:
UPDATE loyalty.account SET status = #{status}
       , closed_at = now()
WHERE id = #{id} AND status IN ('ACTIVE','SUSPENDED')

mapper.select:
SELECT version FROM loyalty.point_account_lock
WHERE tenant_id = #{tenantId} AND program_id = #{programId}
  AND account_id = #{accountId} AND point_type_id = #{pointTypeId}
FOR UPDATE
